}

/* ---------- annotation label with leader ---------- */
function fAnnot(g, label, ax, ay, px, py, fs, bnd) {
  var d = fs * 3.4;
  var lx = ax + px * d, ly = ay + py * d;
  lx = Math.min(Math.max(lx, bnd.x0 + fs * 3.2), bnd.x1 - fs * 3.2);
  ly = Math.min(Math.max(ly, bnd.y0 + fs * 0.9), bnd.y1 - fs * 0.9);
  var dx = ax - lx, dy = ay - ly, len = Math.max(1, Math.sqrt(dx * dx + dy * dy));
  var ux = dx / len, uy = dy / len;
