  var ex = ax - ux * fs * 0.55, ey = ay - uy * fs * 0.55;
  var mx = (sx + ex) / 2 - uy * fs * 0.9, my = (sy + ey) / 2 + ux * fs * 0.9;
  g.path('M' + sx + ',' + sy + ' Q' + mx + ',' + my + ' ' + ex + ',' + ey)
    .fill('none').stroke({ color: INK, width: 1.4, linecap: 'round' });
