/* ---------- one optical panel ---------- */
function drawPanel(o) {
  var g = fdraw.group();
  var x0 = o.x0, y0 = o.y0, w = o.w, h = o.h;
  var by = y0 + h * 0.36, rectH = h * 0.34, cx = x0 + w * 0.47;
  var S = Math.min(w, h);
  var fs = Math.min(16, Math.max(9.5, S * 0.046));
  var sw = Math.max(1.6, S * 0.0078);
  var r = S * 0.135;

  var th1 = o.theta1 * Math.PI / 180;
  var ratio = o.ratio;
  var thc = Math.asin(Math.min(0.9999, ratio)), thcDeg = thc * 180 / Math.PI;
  var s2 = Math.sin(th1) / ratio;
  var grazing = Math.abs(o.theta1 - thcDeg) < 0.9;
  var refr = !grazing && s2 < 1;
  var tir = !grazing && s2 >= 1;
  var th2 = refr ? Math.asin(Math.min(1, s2)) : Math.PI / 2;

  /* medium block */
  var med = g.rect(w, rectH).move(x0, by).fill(fgrad).stroke({ color: '#5f9ec4', width: 1.1 });
  med.css('cursor', 'pointer');
  med.on('mousemove', function (e) { showTooltip('Denser medium n₁ (light travels here)', e); });
  med.on('mouseleave', function () { hideTooltip(); });
