  var grazing = Math.abs(th1d - thc) < 0.9;
  var g = fdraw.group();
  var bw = 205, bh = 80, f = 11.5;
  g.rect(bw, bh).move(x, y).radius(5).fill('#ffffff').opacity(0.93).stroke({ color: '#c3ccd4', width: 1 });
  var tx = x + 10, ty = y + 14, dy = 13.5;
  fTxt(g, 'θ₁ = ' + th1d.toFixed(0) + '°', tx, ty, f, INK, false, 'left');
  var s2txt, s2col;
  if (grazing) { s2txt = 'θ₂ = 90°  (grazing)'; s2col = '#b06a00'; }
  else if (s2 < 1) { s2txt = 'θ₂ = ' + (Math.asin(s2) * 180 / Math.PI).toFixed(1) + '°'; s2col = TEAL; }
  else { s2txt = 'θ₂ = none → total internal refl.'; s2col = '#b03a2e'; }
  fTxt(g, s2txt, tx, ty + dy, f, s2col, false, 'left');
  fTxt(g, 'n₂/n₁ = ' + ratio.toFixed(2) + '      θ_c = ' + thc.toFixed(1) + '°', tx, ty + 2 * dy, f, INK, false, 'left');
