    t.css('pointer-events', 'none');
    var b = t.bbox();
    els.push({ t: t, w: b.width, h: b.height, sub: p.sub });
    wsum += b.width;
  }
  var sx = (align === 'left') ? x : (align === 'right' ? x - wsum : x - wsum / 2);
  for (i = 0; i < els.length; i++) {
    var e = els[i];
    e.t.move(sx, y - e.h / 2 + (e.sub ? size * 0.26 : 0));
    sx += e.w;
  }
  return wsum;
}

/* ---------- geometry helpers ---------- */
function fArrow(g, x, y, ux, uy, size, color) {
  var px = -uy, py = ux;
  var tx = x + ux * size * 0.60, ty = y + uy * size * 0.60;
  var bx = x - ux * size * 0.45, byy = y - uy * size * 0.45;
  g.polygon([[tx, ty], [bx + px * size * 0.40, byy + py * size * 0.40], [bx - px * size * 0.40, byy - py * size * 0.40]])
    .fill(color).stroke('none').css('pointer-events', 'none');
}
function fClamp(cx, cy, ux, uy, b, L) {
  if (ux > 1e-6) L = Math.min(L, (b.x1 - cx) / ux); else if (ux < -1e-6) L = Math.min(L, (b.x0 - cx) / ux);
  if (uy > 1e-6) L = Math.min(L, (b.y1 - cy) / uy); else if (uy < -1e-6) L = Math.min(L, (b.y0 - cy) / uy);
  return Math.max(6, L);
}
function fArc(g, cx, cy, r, a0, a1, dir, color, dash, wdt) {
  var pts = [], n = 28;
  for (var i = 0; i <= n; i++) { var a = a0 + (a1 - a0) * i / n; var d = dir(a); pts.push([cx + r * d[0], cy + r * d[1]]); }
  var p = g.polyline(pts).fill('none').stroke({ color: color, width: wdt || 1.3 }).css('pointer-events', 'none');
  if (dash) p.attr('stroke-dasharray', '5,4');
  return p;
}
var DL = function (a) { return [-Math.sin(a), Math.cos(a)]; };
var DR = function (a) { return [Math.sin(a), Math.cos(a)]; };
var UR = function (a) { return [Math.sin(a), -Math.cos(a)]; };

function fHit(g, x1, y1, x2, y2, wdt, tip, title, body) {
  var h = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: Math.max(14, wdt * 4), opacity: 0, linecap: 'round' });
  h.css('cursor', 'pointer');
  h.on('mousemove', function (e) { showTooltip(tip, e); });
  h.on('mouseleave', function () { hideTooltip(); });
  h.on('click', function () { showPopup(title, body); });
  return h;
}

/* ---------- annotation with curved leader ---------- */
function boxExit(tx, ty, hw, hh, ux, uy) {
  var t = 1e9;
  if (Math.abs(ux) > 1e-6) t = Math.min(t, hw / Math.abs(ux));
  if (Math.abs(uy) > 1e-6) t = Math.min(t, hh / Math.abs(uy));
  return [tx + ux * t, ty + uy * t];
}
function fAnnot(g, label, lx, ly, ax, ay, fs, bend) {
  var t = fTxt(g, label, lx, ly, fs, INK, false, 'center');
  var b = t.bbox();
  var dx = ax - lx, dy = ay - ly, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L;
  var s = boxExit(lx, ly, b.width / 2 + fs * 0.25, b.height / 2 + fs * 0.2, ux, uy);
  var ex = ax - ux * fs * 0.55, ey = ay - uy * fs * 0.55;
  var mx = (s[0] + ex) / 2 - uy * fs * bend, my = (s[1] + ey) / 2 + ux * fs * bend;
  g.path('M' + s[0] + ',' + s[1] + ' Q' + mx + ',' + my + ' ' + ex + ',' + ey)
    .fill('none').stroke({ color: INK, width: Math.max(1.4, fs * 0.09), linecap: 'round' })
    .css('pointer-events', 'none');
  var tgx = ex - mx, tgy = ey - my, tl = Math.sqrt(tgx * tgx + tgy * tgy) || 1;
  fArrow(g, ex, ey, tgx / tl, tgy / tl, fs * 0.95, INK);
}

/* ---------- one optical panel ---------- */
function drawPanel(o) {
  var g = fdraw.group();
  var x0 = o.x0, y0 = o.y0, w = o.w, h = o.h;
  var blockH = Math.min(w / 2.05, h / 1.80);
  var total = blockH * 1.80;
  var top = y0 + (h - total) / 2;
  var by = top + blockH * 0.80;
  var blockBot = by + blockH;
  var cx = x0 + w * 0.47;
  var fs = Math.max(o.fsMin, Math.min(24, blockH * 0.105));
  var sw = Math.max(2, blockH * 0.011);
  var r = blockH * 0.27;

  var th1 = o.theta1 * Math.PI / 180;
  var ratio = o.ratio;
  var thc = Math.asin(Math.min(0.9999, ratio)), thcDeg = thc * 180 / Math.PI;
  var s2 = Math.sin(th1) / ratio;
  var grazing = Math.abs(o.theta1 - thcDeg) < 1.0;
  var refr = !grazing && s2 < 1;
  var tir = !grazing && s2 >= 1;
  var th2 = refr ? Math.asin(Math.min(1, s2)) : Math.PI / 2;

  /* denser medium block */
  var med = g.rect(w, blockH).move(x0, by).fill(fgrad).stroke({ color: '#6aa6c9', width: 1.2 });
  med.css('cursor', 'pointer');
  med.on('mousemove', function (e) { showTooltip('Denser medium n₁ — the light travels inside here', e); });
  med.on('mouseleave', function () { hideTooltip(); });
  med.on('click', function () { showPopup('The denser medium n₁', 'Light starts inside this medium, whose index n₁ is larger than the index n₂ above. Because n₁ > n₂ the refracted ray always bends away from the normal, which is exactly why a critical angle exists.'); });

  /* normal */
  var ntop = top + blockH * 0.16;
  g.line(cx, ntop, cx, blockBot - blockH * 0.02).stroke({ color: '#222', width: 1.4, dasharray: '8,6' }).css('pointer-events', 'none');
  fHit(g, cx, ntop, cx, blockBot, 1.4, 'Normal — every angle is measured from this line',
    'The normal', 'The dashed line is perpendicular to the interface. Every angle in Snell\'s law — θ₁, θ₂ and θ_c — is measured from this normal, not from the surface.');

  /* bounds: rays inside n₁ are clamped to the block itself */
  var lb = { x0: x0, x1: x0 + w, y0: by, y1: blockBot };
  var ub = { x0: x0 + w * 0.03, x1: x0 + w - w * 0.03, y0: top + blockH * (o.detailed ? 0.24 : 0.10), y1: by };

  var si = Math.sin(th1), ci = Math.cos(th1);

  /* incident ray */
  var Li = fClamp(cx, by, -si, ci, lb, blockH * 3);
  var ix = cx - Li * si, iy = by + Li * ci;
  g.line(ix, iy, cx, by).stroke({ color: TEAL, width: sw, linecap: 'round' }).css('pointer-events', 'none');
  fArrow(g, cx - Li * 0.52 * si, by + Li * 0.52 * ci, si, -ci, sw * 3.4, TEAL);
  fHit(g, ix, iy, cx, by, sw, 'Incident ray, θ₁ = ' + o.theta1.toFixed(0) + '°',
    'Incident ray', 'Light travelling inside the dense medium n₁ strikes the boundary at angle θ₁ from the normal. Snell\'s law n₁ sin θ₁ = n₂ sin θ₂ decides what happens next.');

  /* reflected ray */
  var Lr = fClamp(cx, by, si, ci, lb, blockH * 3);
  var rx = cx + Lr * si, ry = by + Lr * ci;
  var rcol = tir ? TEAL_HOT : TEAL, rwid = tir ? sw * 1.5 : sw;
  g.line(cx, by, rx, ry).stroke({ color: rcol, width: rwid, linecap: 'round' }).css('pointer-events', 'none');
  fArrow(g, cx + Lr * 0.52 * si, by + Lr * 0.52 * ci, si, ci, rwid * 3.2, rcol);
  fHit(g, cx, by, rx, ry, rwid, tir ? 'Reflected ray — now carries 100% of the light' : 'Reflected ray, also at θ₁',
    'Reflected ray', 'Reflection always happens, at an angle equal to θ₁ on the other side of the normal. Beyond the critical angle it is the only surviving ray, so it carries all of the light.');

  /* refracted ray */
  var fx = 0, fy = 0;
  if (refr) {
    var s2s = Math.sin(th2), c2 = Math.cos(th2);
    var L2 = fClamp(cx, by, s2s, -c2, ub, blockH * 0.95);
    fx = cx + L2 * s2s; fy = by - L2 * c2;
    g.line(cx, by, fx, fy).stroke({ color: TEAL, width: sw, linecap: 'round' }).css('pointer-events', 'none');
    fArrow(g, cx + L2 * 0.55 * s2s, by - L2 * 0.55 * c2, s2s, -c2, sw * 3.2, TEAL);
    fHit(g, cx, by, fx, fy, sw, 'Refracted ray, θ₂ = ' + (th2 * 180 / Math.PI).toFixed(1) + '°',
      'Refracted ray', 'The transmitted ray bends away from the normal because n₂ < n₁. As θ₁ grows, θ₂ races toward 90° much faster — and once sin θ₁ exceeds n₂/n₁ there is no angle θ₂ left to use.');
  } else if (grazing) {
    var Lg = Math.min(w * 0.40, x0 + w - 8 - cx);
    g.line(cx, by, cx + Lg, by).stroke({ color: TEAL, width: sw, linecap: 'round' }).css('pointer-events', 'none');
    fArrow(g, cx + Lg * 0.62, by, 1, 0, sw * 3.2, TEAL);
    fHit(g, cx, by, cx + Lg, by, sw, 'Refracted ray grazes the surface: θ₂ = 90°',
      'Grazing refraction', 'At exactly the critical angle the refracted ray lies flat along the interface, θ₂ = 90°. Putting θ₂ = 90° into Snell\'s law gives sin θ_c = n₂/n₁.');
    var sq = blockH * 0.10;
    g.rect(sq, sq).move(cx, by - sq).fill('none').stroke({ color: '#222', width: 1.4 }).css('pointer-events', 'none');
  }

  /* dashed critical-angle reference ray (secondary, lighter) */
  var showC = o.showCrit;
  if (showC) {
    var Lc = fClamp(cx, by, -Math.sin(thc), Math.cos(thc), lb, blockH * 3) * 0.88;
    var cxr = cx - Lc * Math.sin(thc), cyr = by + Lc * Math.cos(thc);
    g.line(cxr, cyr, cx, by).stroke({ color: TEAL, width: Math.max(1.5, sw * 0.7), dasharray: '10,6', opacity: 0.75 }).css('pointer-events', 'none');
    fArc(g, cx, by, r * 2.05, 0, thc, DL, TEAL, true, 1.2);
    fHit(g, cxr, cyr, cx, by, sw, 'Critical-angle reference: θc = ' + thcDeg.toFixed(1) + '°',
      'The critical angle θc', 'This dashed ray is drawn at sin θ_c = n₂/n₁. Any incident ray inside this angle refracts; any ray outside it is totally internally reflected. Change the index ratio and the dashed line swings to a new threshold.');
  }

  /* angle arcs */
  fArc(g, cx, by, r, 0, th1, DL, INK, false, 1.3);
  fArc(g, cx, by, r, 0, th1, DR, INK, false, 1.3);
  if (refr) fArc(g, cx, by, r * 0.92, 0, th2, UR, INK, false, 1.3);

  /* ---------- text layer (drawn last, haloed) ---------- */
  fTxt(g, 'n₁', x0 + w * 0.90, by + blockH * 0.15, fs * 1.05, INK, true, 'center');
  fTxt(g, 'n₂', x0 + w * 0.07, by - blockH * 0.45, fs * 1.05, INK, true, 'center');

  /* angle labels */
  var aL, aC;
  if (showC && thc < th1) { aL = (thc + th1) / 2; aC = thc * 0.48; }
  else if (showC) { aL = th1 * 0.50; aC = (th1 + thc) / 2; }
  else { aL = th1 * 0.55; aC = null; }
  var rl = r * 1.48;
  fTxt(g, 'θ₁', cx - rl * Math.sin(aL), by + rl * Math.cos(aL), fs, INK, true, 'center');
  fTxt(g, 'θ₁', cx + r * 1.48 * Math.sin(th1 * 0.55), by + r * 1.48 * Math.cos(th1 * 0.55), fs, INK, true, 'center');
  if (showC) {
    var rc = (Math.abs(aC - aL) < 0.20) ? r * 2.5 : r * 1.48;
    fRich(g, [{ s: 'θ', it: true }, { s: 'c', sub: true }], cx - rc * Math.sin(aC), by + rc * Math.cos(aC), fs, TEAL, 'center');
  }
  if (refr) {
    var la2 = th2 * 0.55;
    fTxt(g, 'θ₂', cx + r * 1.42 * Math.sin(la2), by - r * 1.42 * Math.cos(la2), fs, INK, true, 'center');
  } else if (grazing) {
    fTxt(g, 'θ₂ = 90°', cx + blockH * 0.10 + fs * 2.7, by - blockH * 0.10 - fs * 0.55, fs, INK, false, 'center');
  }
  if (tir) {
    fTxt(g, 'Total internal', x0 + w * 0.79, by + blockH * 0.56, fs * 0.92, INK, false, 'center');
    fTxt(g, 'reflection', x0 + w * 0.79, by + blockH * 0.56 + fs * 1.15, fs * 0.92, INK, false, 'center');
  }

  /* word annotations with curved leaders (live view only) */
  if (o.detailed) {
    var af = fs * 0.88;
    /* incident */
    var yRay = (si > 0.02) ? by + (cx - (x0 + w * 0.14)) * (ci / si) : Infinity;
    var ilx = x0 + w * 0.14, ily;
    if (!isFinite(yRay) || yRay > blockBot) ily = by + blockH * 0.42;
    else if (yRay > by + af * 2.6) ily = yRay - af * 1.35;
    else ily = yRay + af * 1.55;
    ily = Math.min(Math.max(ily, by + af * 0.9), blockBot - af * 0.9);
    fAnnot(g, 'Incident ray', ilx, ily, cx - Li * 0.62 * si, by + Li * 0.62 * ci, af, 0.9);
    /* reflected — placed below the block, in clear space */
    fAnnot(g, 'Reflected ray', cx + w * 0.24, blockBot + af * 1.9,
      cx + Lr * 0.70 * si, by + Lr * 0.70 * ci, af, -0.9);
    /* refracted — top clear band */
    if (refr) {
      var mlx = Math.min(Math.max((cx + fx) / 2 - af * 1.0, x0 + w * 0.10), x0 + w * 0.86);
      fAnnot(g, 'Refracted ray', mlx, top + af * 0.9,
        cx + (fx - cx) * 0.78, by + (fy - by) * 0.78, af, 0.8);
    }
  }
  return g;
}

/* ---------- readout (bottom-left, clear of artwork) ---------- */
function drawReadout(x, y, bw, bh, th1d, ratio) {
  var thc = Math.asin(Math.min(0.9999, ratio)) * 180 / Math.PI;
  var s2 = Math.sin(th1d * Math.PI / 180) / ratio;
  var grazing = Math.abs(th1d - thc) < 1.0;
  var g = fdraw.group();
  var f = 17;
  g.rect(bw, bh).move(x, y).radius(6).fill('#ffffff').opacity(0.96).stroke({ color: '#b9c4cd', width: 1.2 });
  var tx = x + 13, ty = y + 19, dy = f * 1.28;
  fTxt(g, 'θ₁ = ' + th1d.toFixed(0) + '°', tx, ty, f, INK, false, 'left');
  var s2txt, s2col;
  if (grazing) { s2txt = 'θ₂ = 90°  (grazing)'; s2col = '#a35c00'; }
  else if (s2 < 1) { s2txt = 'θ₂ = ' + (Math.asin(s2) * 180 / Math.PI).toFixed(1) + '°'; s2col = TEAL; }
  else { s2txt = 'θ₂ = none → total internal refl.'; s2col = '#a63428'; }
  fTxt(g, s2txt, tx, ty + dy, f, s2col, false, 'left');
  var wsum = fRich(g, [{ s: 'n₂/n₁ = ' + ratio.toFixed(2) + '     ' }, { s: 'θ', it: true }, { s: 'c', sub: true },
  { s: ' = ' + thc.toFixed(1) + '°' }], tx, ty + 2 * dy, f, INK, 'left');
  fTxt(g, 'n₁ sin θ₁ = n₂ sin θ₂', tx, ty + 3 * dy + 5, f * 0.94, '#444', true, 'left');
  fRich(g, [{ s: 'sin ' }, { s: 'θ', it: true }, { s: 'c', sub: true }, { s: ' = n₂/n₁' }],
    tx, ty + 4 * dy + 5, f * 0.94, '#444', 'left');
  return g;
}

/* ---------- render ---------- */
function render() {
  fdraw.clear();
  fgrad = fdraw.gradient('linear', function (add) {
    add.stop(0, '#a4c6da'); add.stop(0.45, '#dcecf4'); add.stop(0.74, '#ffffff'); add.stop(1, '#cfe3ee');
  });
  fgrad.from(0, 0).to(1, 0.75);

  if (!fstate.three) {
    fdraw.viewbox(0, 0, 720, 662);
    drawPanel({
      x0: 14, y0: 6, w: 692, h: 536, fsMin: 17, detailed: true,
      theta1: fstate.theta1, ratio: fstate.ratio, showCrit: fstate.showCrit
    });
    drawReadout(14, 548, 384, 106, fstate.theta1, fstate.ratio);
  } else {
    fdraw.viewbox(0, 0, 990, 470);
    var gap = 14, pw = (990 - 4 * gap) / 3, ph = 386, py = 6;
    var thc = Math.asin(Math.min(0.9999, fstate.ratio)) * 180 / Math.PI;
    var angs = [Math.max(6, thc - 18), thc, Math.min(88, thc + 16)];
    var caps = ['(a)', '(b)', '(c)'];
    var subs = ['θ₁ < θc : refraction', 'θ₁ = θc : grazing', 'θ₁ > θc : total reflection'];
    for (var i = 0; i < 3; i++) {
      var px = gap + i * (pw + gap);
      drawPanel({
        x0: px, y0: py, w: pw, h: ph, fsMin: 18, detailed: false,
        theta1: angs[i], ratio: fstate.ratio, showCrit: fstate.showCrit && i === 2
      });
      fTxt(fdraw, caps[i], px + pw * 0.47, py + ph + 20, 21, INK, false, 'center');
      fTxt(fdraw, subs[i], px + pw * 0.47, py + ph + 47, 17, '#555', false, 'center');
    }
  }
}

/* ---------- controls ---------- */
function update_incidentAngle(v) { fstate.theta1 = v; render(); }
function update_indexRatio(v) { fstate.ratio = v; render(); }
function toggle_viewMode(on) { fstate.three = on; render(); }
function toggle_showCriticalRef(on) { fstate.showCrit = on; render(); }
function showKeyInsight() {
  showPopup('Key insight', 'Total internal reflection is not a new phenomenon but the point where refraction runs out of room: once θ₂ would have to exceed 90°, Snell\'s law has no solution and all the light must reflect — and that threshold angle is fixed by sin θ_c = n₂/n₁.');
}

/* ---------- demo steps ---------- */
var STEPS = [
  { t: 'Ordinary refraction', n: 'At a modest incident angle the ray splits: part reflects back into the dense medium at the same angle θ₁, and part refracts into n₂, bent away from the normal so that θ₂ > θ₁.', s: { a: 25, r: 0.67, v: false, c: false } },
  { t: 'Bending farther out', n: 'Push θ₁ higher and the refracted ray swings rapidly toward the surface — θ₂ grows much faster than θ₁ because n₁ sin θ₁ = n₂ sin θ₂ with n₁ > n₂.', s: { a: 36, r: 0.67, v: false, c: false } },
  { t: 'The critical angle', n: 'At θ₁ = θc the refracted ray lies flat along the boundary, θ₂ = 90°. This is exactly where sin θc = n₂/n₁ — the dashed reference ray now appears right under the incident ray.', s: { a: 42, r: 0.67, v: false, c: true } },
  { t: 'Total internal reflection', n: 'Beyond θc there is no solution for θ₂ — the refracted ray disappears entirely and 100% of the light returns into n₁ as the reflected ray.', s: { a: 60, r: 0.67, v: false, c: true } },
  { t: 'Moving the threshold', n: 'Hold θ₁ fixed at 60° and raise n₂/n₁: the dashed θc line swings outward and, once θc exceeds 60°, the refracted ray reappears. The threshold, not the ray, is what the indices control.', s: { a: 60, r: 0.92, v: false, c: true } },
  { t: 'Three snapshots of one sweep', n: 'Displayed side by side, panels (a), (b) and (c) are simply θ₁ < θc, θ₁ = θc and θ₁ > θc — one continuous story frozen at three moments.', s: { a: 60, r: 0.67, v: true, c: true } }
];
var curStep = 0;
function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var st = STEPS[curStep].s;
  document.getElementById('incidentAngleInput').value = st.a;
  document.getElementById('incidentAngleVal').value = st.a;
  document.getElementById('indexRatioInput').value = st.r;
  document.getElementById('indexRatioVal').value = st.r.toFixed(2);
  document.getElementById('viewModeInput').checked = st.v;
  document.getElementById('showCriticalRefInput').checked = st.c;
  fstate.theta1 = st.a; fstate.ratio = st.r; fstate.three = st.v; fstate.showCrit = st.c;
  document.getElementById('demoTitle').textContent = (curStep + 1) + '. ' + STEPS[curStep].t;
  document.getElementById('demoNarration').textContent = STEPS[curStep].n;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
