var TEAL = '#1B7A8C', TEAL_HOT = '#0F8FA8', INK = '#1a1a1a';
var SERIF = 'Georgia, "Times New Roman", serif';
var fdraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var fstate = { theta1: 25, ratio: 0.67, single: false, showCrit: true, readout: false };
var fgrad = null;

/* ---------- text helpers ---------- */
function fTxt(g, str, x, y, size, color, italic, align) {
  var t = g.text(str).font({ family: SERIF, size: size, style: italic ? 'italic' : 'normal' }).fill(color || INK);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': Math.max(2.4, size * 0.30), 'stroke-linejoin': 'round' });
  t.css('pointer-events', 'none');
  var b = t.bbox();
  if (align === 'left') t.move(x, y - b.height / 2);
  else if (align === 'right') t.move(x - b.width, y - b.height / 2);
  else t.move(x - b.width / 2, y - b.height / 2);
  return t;
}
/* rich text with subscripts: parts = [{s:'θ',it:true},{s:'c',sub:true}] — every run
   is positioned at an explicit x offset, never with trailing spaces */
function fRich(g, parts, x, y, size, color, align) {
  var els = [], wsum = 0, i;
  for (i = 0; i < parts.length; i++) {
    var p = parts[i];
    var sz = p.sub ? size * 0.72 : size;
    var t = g.text(p.s).font({ family: SERIF, size: sz, style: p.it ? 'italic' : 'normal' }).fill(p.c || color || INK);
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': Math.max(2.4, sz * 0.30), 'stroke-linejoin': 'round' });
    t.css('pointer-events', 'none');
    var b = t.bbox();
    els.push({ t: t, w: b.width + (p.gap || 0), h: b.height, sub: p.sub });
    wsum += b.width + (p.gap || 0);
  }
  var sx = (align === 'left') ? x : (align === 'right' ? x - wsum : x - wsum / 2);
  for (i = 0; i < els.length; i++) {
    var e = els[i];
    e.t.move(sx, y - e.h / 2 + (e.sub ? size * 0.26 : 0));
    sx += e.w;
  }
  return wsum;
}

/* ---------- geometry helpers ---------- */
function fArrow(g, x, y, ux, uy, size, color) {
  var px = -uy, py = ux;
  var tx = x + ux * size * 0.60, ty = y + uy * size * 0.60;
  var bx = x - ux * size * 0.45, byy = y - uy * size * 0.45;
  g.polygon([[tx, ty], [bx + px * size * 0.40, byy + py * size * 0.40], [bx - px * size * 0.40, byy - py * size * 0.40]])
    .fill(color).stroke('none').css('pointer-events', 'none');
}
function fClamp(cx, cy, ux, uy, b, L) {
  if (ux > 1e-6) L = Math.min(L, (b.x1 - cx) / ux); else if (ux < -1e-6) L = Math.min(L, (b.x0 - cx) / ux);
  if (uy > 1e-6) L = Math.min(L, (b.y1 - cy) / uy); else if (uy < -1e-6) L = Math.min(L, (b.y0 - cy) / uy);
  return Math.max(6, L);
}
function fArc(g, cx, cy, r, a0, a1, dir, color, dash, wdt) {
  var pts = [], n = 28;
  for (var i = 0; i <= n; i++) { var a = a0 + (a1 - a0) * i / n; var d = dir(a); pts.push([cx + r * d[0], cy + r * d[1]]); }
  var p = g.polyline(pts).fill('none').stroke({ color: color, width: wdt || 1.3 }).css('pointer-events', 'none');
  if (dash) p.attr('stroke-dasharray', '5,4');
  return p;
}
var DL = function (a) { return [-Math.sin(a), Math.cos(a)]; };
var DR = function (a) { return [Math.sin(a), Math.cos(a)]; };
var UR = function (a) { return [Math.sin(a), -Math.cos(a)]; };

function fHit(g, x1, y1, x2, y2, wdt, tip, title, body) {
  var h = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: Math.max(14, wdt * 4), opacity: 0, linecap: 'round' });
  h.css('cursor', 'pointer');
  h.on('mousemove', function (e) { showTooltip(tip, e); });
  h.on('mouseleave', function () { hideTooltip(); });
  h.on('click', function () { showPopup(title, body); });
  return h;
}

/* ---------- annotation with curved leader ---------- */
function boxExit(tx, ty, hw, hh, ux, uy) {
  var t = 1e9;
  if (Math.abs(ux) > 1e-6) t = Math.min(t, hw / Math.abs(ux));
  if (Math.abs(uy) > 1e-6) t = Math.min(t, hh / Math.abs(uy));
  return [tx + ux * t, ty + uy * t];
}
function fAnnot(g, label, lx, ly, ax, ay, fs, bend) {
  var t = fTxt(g, label, lx, ly, fs, INK, false, 'center');
  var b = t.bbox();
  var dx = ax - lx, dy = ay - ly, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L;
  var s = boxExit(lx, ly, b.width / 2 + fs * 0.25, b.height / 2 + fs * 0.2, ux, uy);
  var ex = ax - ux * fs * 0.55, ey = ay - uy * fs * 0.55;
  var mx = (s[0] + ex) / 2 - uy * fs * bend, my = (s[1] + ey) / 2 + ux * fs * bend;
  g.path('M' + s[0] + ',' + s[1] + ' Q' + mx + ',' + my + ' ' + ex + ',' + ey)
    .fill('none').stroke({ color: INK, width: Math.max(1.3, fs * 0.085), linecap: 'round' })
    .css('pointer-events', 'none');
  var tgx = ex - mx, tgy = ey - my, tl = Math.sqrt(tgx * tgx + tgy * tgy) || 1;
  fArrow(g, ex, ey, tgx / tl, tgy / tl, fs * 0.95, INK);
}

/* ---------- one optical panel ---------- */
function drawPanel(o) {
  var g = fdraw.group();
  var x0 = o.x0, y0 = o.y0, w = o.w, h = o.h;
  var blockH = Math.min(w / 2.2, h * 0.46);
  var upperH = blockH * 0.85;
  var top = y0 + (h - blockH - upperH) / 2;
  var by = top + upperH, blockBot = by + blockH;
  var cx = x0 + w * 0.47;
  var fs = Math.max(o.fsMin, Math.min(26, blockH * 0.108));
  var sw = Math.max(2, blockH * 0.0125);
  var r = blockH * 0.30;
  var ov = blockH * 0.075;                       /* rays overshoot the vertex slightly */

  var th1 = o.theta1 * Math.PI / 180;
  var ratio = o.ratio;
  var thc = Math.asin(Math.min(0.9999, ratio)), thcDeg = thc * 180 / Math.PI;
  var s2 = Math.sin(th1) / ratio;
  var grazing = Math.abs(o.theta1 - thcDeg) < 0.8;
  var refr = !grazing && s2 < 1;
  var tir = !grazing && s2 >= 1;
  var th2 = refr ? Math.asin(Math.min(1, s2)) : Math.PI / 2;

  /* denser medium block */
  var med = g.rect(w, blockH).move(x0, by).fill(fgrad).stroke({ color: '#7fb2cc', width: 1.1 });
  med.css('cursor', 'pointer');
  med.on('mousemove', function (e) { showTooltip('Denser medium n₁ — the light travels inside here', e); });
  med.on('mouseleave', function () { hideTooltip(); });
  med.on('click', function () { showPopup('The denser medium n₁', 'Light starts inside this medium, whose index n₁ is larger than the index n₂ above. Because n₁ > n₂ the refracted ray always bends away from the normal, which is exactly why a critical angle exists.'); });

  /* normal */
  var ntop = top + blockH * 0.12;
  g.line(cx, ntop, cx, blockBot - blockH * 0.02).stroke({ color: '#222', width: 1.4, dasharray: '8,6' }).css('pointer-events', 'none');
  fHit(g, cx, ntop, cx, blockBot, 1.4, 'Normal — every angle is measured from this line',
    'The normal', 'The dashed line is perpendicular to the interface. Every angle in Snell\'s law — θ₁, θ₂ and θ_c — is measured from this normal, not from the surface.');

  /* bounds (rays are allowed to overshoot the block edge a little, as in the source) */
  var lb = { x0: x0 - w * 0.012, x1: x0 + w + w * 0.012, y0: by, y1: blockBot + blockH * 0.05 };
  var ub = { x0: x0 + w * 0.02, x1: x0 + w - w * 0.02, y0: top + blockH * (o.annot ? 0.22 : 0.08), y1: by };

  var si = Math.sin(th1), ci = Math.cos(th1);

  /* incident ray (tail lower-left → vertex, overshooting slightly past it) */
  var Li = fClamp(cx, by, -si, ci, lb, blockH * 3);
  var ix = cx - Li * si, iy = by + Li * ci;
  g.line(ix, iy, cx + ov * si, by - ov * ci).stroke({ color: TEAL, width: sw, linecap: 'round' }).css('pointer-events', 'none');
  fArrow(g, cx - Li * 0.40 * si, by + Li * 0.40 * ci, si, -ci, sw * 3.4, TEAL);
  fHit(g, ix, iy, cx, by, sw, 'Incident ray, θ₁ = ' + o.theta1.toFixed(0) + '°',
    'Incident ray', 'Light travelling inside the dense medium n₁ strikes the boundary at angle θ₁ from the normal. Snell\'s law n₁ sin θ₁ = n₂ sin θ₂ decides what happens next.');

  /* reflected ray */
  var Lr = fClamp(cx, by, si, ci, lb, blockH * 3);
  var rx = cx + Lr * si, ry = by + Lr * ci;
  var rcol = tir ? TEAL_HOT : TEAL, rwid = tir ? sw * 1.45 : sw;
  g.line(cx - ov * si, by - ov * ci, rx, ry).stroke({ color: rcol, width: rwid, linecap: 'round' }).css('pointer-events', 'none');
  fArrow(g, cx + Lr * 0.86 * si, by + Lr * 0.86 * ci, si, ci, rwid * 3.2, rcol);
  fHit(g, cx, by, rx, ry, rwid, tir ? 'Reflected ray — now carries 100% of the light' : 'Reflected ray, also at θ₁',
    'Reflected ray', 'Reflection always happens, at an angle equal to θ₁ on the other side of the normal. Beyond the critical angle it is the only surviving ray, so it carries all of the light.');

  /* refracted ray */
  var fx = 0, fy = 0;
  if (refr) {
    var s2s = Math.sin(th2), c2 = Math.cos(th2);
    var L2 = fClamp(cx, by, s2s, -c2, ub, blockH * 1.05);
    fx = cx + L2 * s2s; fy = by - L2 * c2;
    g.line(cx - ov * 0.7 * s2s, by + ov * 0.7 * c2, fx, fy).stroke({ color: TEAL, width: sw, linecap: 'round' }).css('pointer-events', 'none');
    fArrow(g, cx + L2 * 0.86 * s2s, by - L2 * 0.86 * c2, s2s, -c2, sw * 3.2, TEAL);
    fHit(g, cx, by, fx, fy, sw, 'Refracted ray, θ₂ = ' + (th2 * 180 / Math.PI).toFixed(1) + '°',
      'Refracted ray', 'The transmitted ray bends away from the normal because n₂ < n₁. As θ₁ grows, θ₂ races toward 90° much faster — and once sin θ₁ exceeds n₂/n₁ there is no angle θ₂ left to use.');
  } else if (grazing) {
    var Lg = Math.min(w * 0.42, x0 + w - w * 0.03 - cx);
    g.line(cx, by, cx + Lg, by).stroke({ color: TEAL, width: sw, linecap: 'round' }).css('pointer-events', 'none');
    fArrow(g, cx + Lg * 0.87, by, 1, 0, sw * 3.2, TEAL);
    fHit(g, cx, by, cx + Lg, by, sw, 'Refracted ray grazes the surface: θ₂ = 90°',
      'Grazing refraction', 'At exactly the critical angle the refracted ray lies flat along the interface, θ₂ = 90°. Putting θ₂ = 90° into Snell\'s law gives sin θ_c = n₂/n₁.');
    /* right-angle square between normal and boundary (source panel b) */
    var sq = blockH * 0.115;
    g.rect(sq, sq).move(cx, by - sq).fill('none').stroke({ color: '#222', width: 1.4 }).css('pointer-events', 'none');
  }

  /* dashed critical-angle reference ray */
  var showC = o.showCrit;
  var cxr = 0, cyr = 0;
  if (showC) {
    var Lc = fClamp(cx, by, -Math.sin(thc), Math.cos(thc), lb, blockH * 3) * 0.90;
    cxr = cx - Lc * Math.sin(thc); cyr = by + Lc * Math.cos(thc);
    g.line(cxr, cyr, cx, by).stroke({ color: TEAL, width: Math.max(1.6, sw * 0.8), dasharray: '10,6', opacity: 0.85 }).css('pointer-events', 'none');
    fHit(g, cxr, cyr, cx, by, sw, 'Critical-angle reference: θc = ' + thcDeg.toFixed(1) + '°',
      'The critical angle θc', 'This dashed ray is drawn at sin θ_c = n₂/n₁. Any incident ray inside this angle refracts; any ray outside it is totally internally reflected. Change the index ratio and the dashed line swings to a new threshold.');
  }

  /* angle arcs */
  fArc(g, cx, by, r, 0, th1, DL, INK, false, 1.3);
  fArc(g, cx, by, r, 0, th1, DR, INK, false, 1.3);
  if (refr) fArc(g, cx, by, r * 0.92, 0, th2, UR, INK, false, 1.3);
  if (showC && Math.abs(thc - th1) > 0.02) fArc(g, cx, by, r * 1.70, 0, thc, DL, TEAL, true, 1.2);

  /* ---------- text layer (drawn last, haloed) ---------- */
  fTxt(g, 'n₁', x0 + w * 0.90, by + blockH * 0.16, fs * 1.08, INK, true, 'center');
  fTxt(g, 'n₂', x0 + w * 0.08, by - blockH * 0.50, fs * 1.08, INK, true, 'center');

  var rl = r * 1.50;
  if (grazing) {
    fRich(g, [{ s: 'θ', it: true }, { s: 'c', sub: true }], cx - rl * Math.sin(th1 * 0.55), by + rl * Math.cos(th1 * 0.55), fs, INK, 'center');
    fRich(g, [{ s: 'θ', it: true }, { s: 'c', sub: true }], cx + rl * Math.sin(th1 * 0.55), by + rl * Math.cos(th1 * 0.55), fs, INK, 'center');
    fTxt(g, 'θ₂ = 90°', cx + blockH * 0.135 + fs * 0.45, by - blockH * 0.075, fs, INK, false, 'left');
  } else {
    var leftIsCrit = showC && tir;               /* source panel (c): left arc reads θc */
    if (leftIsCrit) {
      fRich(g, [{ s: 'θ', it: true }, { s: 'c', sub: true }], cx - r * 2.10 * Math.sin(thc * 0.55), by + r * 2.10 * Math.cos(thc * 0.55), fs, INK, 'center');
      fTxt(g, 'θ₁', cx - rl * Math.sin(th1 * 0.55), by + rl * Math.cos(th1 * 0.55), fs, INK, true, 'center');
    } else {
      fTxt(g, 'θ₁', cx - rl * Math.sin(th1 * 0.55), by + rl * Math.cos(th1 * 0.55), fs, INK, true, 'center');
      if (showC) fRich(g, [{ s: 'θ', it: true }, { s: 'c', sub: true }],
        cx - r * 2.10 * Math.sin(thc * 0.55), by + r * 2.10 * Math.cos(thc * 0.55), fs, TEAL, 'center');
    }
    fTxt(g, 'θ₁', cx + rl * Math.sin(th1 * 0.55), by + rl * Math.cos(th1 * 0.55), fs, INK, true, 'center');
    if (refr) fTxt(g, 'θ₂', cx + r * 1.44 * Math.sin(th2 * 0.55), by - r * 1.44 * Math.cos(th2 * 0.55), fs, INK, true, 'center');
  }

  if (tir) {   /* source panel (c) wording, two lines inside the lower medium */
    fTxt(g, 'Total internal', x0 + w * 0.79, by + blockH * 0.30, fs * 0.98, INK, false, 'center');
    fTxt(g, 'reflection', x0 + w * 0.79, by + blockH * 0.30 + fs * 1.18, fs * 0.98, INK, false, 'center');
  }

  /* word annotations with curved leaders (source panel (a) only / live panel) */
  if (o.annot) {
    var af = fs * 0.92;
    fAnnot(g, 'Incident ray', x0 + w * 0.15, by - af * 1.05,
      cx - Li * 0.55 * si, by + Li * 0.55 * ci, af, 0.7);
    fAnnot(g, 'Reflected ray', cx + w * 0.24, blockBot + af * 1.7,
      cx + Lr * 0.62 * si, by + Lr * 0.62 * ci, af, -0.9);
    if (refr) {
      var mlx = Math.min(Math.max(cx + (fx - cx) * 0.45, x0 + w * 0.18), x0 + w * 0.80);
      fAnnot(g, 'Refracted ray', mlx, top + af * 0.85,
        cx + (fx - cx) * 0.72, by + (fy - by) * 0.72, af, 0.8);
    }
  }
  return g;
}

/* ---------- collapsible numeric readout chip ---------- */
function drawChip(x, y) {
  var g = fdraw.group();
  var exp = fstate.readout, f = 15.5;
  var th1d = fstate.theta1, ratio = fstate.ratio;
  var thc = Math.asin(Math.min(0.9999, ratio)) * 180 / Math.PI;
  var s2 = Math.sin(th1d * Math.PI / 180) / ratio;
  var graz = Math.abs(th1d - thc) < 0.8;
  var live = fstate.single;
  var w = exp ? 252 : 156, h = exp ? (live ? 136 : 116) : 27;
  var bg = g.rect(w, h).move(x, y).radius(6).fill('#ffffff').opacity(0.96).stroke({ color: '#b9c4cd', width: 1.1 });
  bg.css('cursor', 'pointer');
  bg.on('mousemove', function (e) { showTooltip(exp ? 'Click to collapse the readout' : 'Click to expand the numeric readout', e); });
  bg.on('mouseleave', function () { hideTooltip(); });
  bg.on('click', function () { toggle_showReadout(!fstate.readout); document.getElementById('showReadoutInput').checked = fstate.readout; });

  var tx = x + 12, dy = f * 1.30;
  if (!exp) {
    fRich(g, [{ s: '▸', gap: 8 }, { s: 'θ', it: true }, { s: 'c', sub: true, gap: 2 },
    { s: '= ' + thc.toFixed(1) + '°', gap: 0 }], tx, y + h / 2, f, INK, 'left');
    return g;
  }
  var ty = y + 18;
  fTxt(g, '▾', x + w - 16, y + 15, f * 0.85, '#666', false, 'center');
  var i = 0;
  if (live) {
    fTxt(g, 'θ₁ = ' + th1d.toFixed(0) + '°', tx, ty + i * dy, f, INK, false, 'left'); i++;
    var s2txt, s2col;
    if (graz) { s2txt = 'θ₂ = 90°  (grazing)'; s2col = '#a35c00'; }
    else if (s2 < 1) { s2txt = 'θ₂ = ' + (Math.asin(s2) * 180 / Math.PI).toFixed(1) + '°'; s2col = TEAL; }
    else { s2txt = 'θ₂ = none  (total refl.)'; s2col = '#a63428'; }
    fTxt(g, s2txt, tx, ty + i * dy, f, s2col, false, 'left'); i++;
  } else {
    fTxt(g, '(a) θ₁ < θc   (b) θ₁ = θc   (c) θ₁ > θc', tx, ty + i * dy, f * 0.86, '#444', false, 'left'); i++;
  }
  fTxt(g, 'n₂/n₁ = ' + ratio.toFixed(2), tx, ty + i * dy, f, INK, false, 'left'); i++;
  fRich(g, [{ s: 'θ', it: true }, { s: 'c', sub: true, gap: 3 }, { s: '= ' + thc.toFixed(1) + '°' }],
    tx, ty + i * dy, f, INK, 'left'); i++;
  fTxt(g, 'n₁ sin θ₁ = n₂ sin θ₂', tx, ty + i * dy + 5, f * 0.92, '#555', true, 'left'); i++;
  fRich(g, [{ s: 'sin ', it: true }, { s: 'θ', it: true }, { s: 'c', sub: true, gap: 3 }, { s: '= n₂/n₁', it: true }],
    tx, ty + i * dy + 5, f * 0.92, '#555', 'left');
  return g;
}

/* ---------- render ---------- */
function render() {
  fdraw.clear();
  fgrad = fdraw.gradient('linear', function (add) {
    add.stop(0, '#a4c6da'); add.stop(0.45, '#dcecf4'); add.stop(0.74, '#ffffff'); add.stop(1, '#cfe3ee');
  });
  fgrad.from(0, 0).to(1, 0.75);

  if (fstate.single) {
    var chipH = fstate.readout ? 136 : 27;
    var vbH = 600;
    fdraw.viewbox(0, 0, 720, vbH);
    drawPanel({
      x0: 10, y0: 4, w: 700, h: vbH - chipH - 26, fsMin: 17, annot: true,
      theta1: fstate.theta1, ratio: fstate.ratio, showCrit: fstate.showCrit
    });
    drawChip(12, vbH - chipH - 10);
  } else {
    var exp = fstate.readout;
    var vbH2 = exp ? 540 : 400;
    fdraw.viewbox(0, 0, 990, vbH2);
    var gap = 16, pw = (990 - 4 * gap) / 3, ph = 340, py = 6;
    var thc = Math.asin(Math.min(0.9999, fstate.ratio)) * 180 / Math.PI;
    var angs = [Math.max(6, thc - 18), thc, Math.min(88, thc + 17)];
    var caps = ['(a)', '(b)', '(c)'];
    for (var i = 0; i < 3; i++) {
      var px = gap + i * (pw + gap);
      drawPanel({
        x0: px, y0: py, w: pw, h: ph, fsMin: 15, annot: (i === 0),
        theta1: angs[i], ratio: fstate.ratio,
        showCrit: (i === 2) ? true : (fstate.showCrit && i === 0)
      });
      fTxt(fdraw, caps[i], px + pw * 0.47, py + ph + 18, 20, INK, false, 'center');
    }
    drawChip(exp ? 20 : 814, exp ? 400 : 368);
  }
}

/* ---------- controls ---------- */
function update_incidentAngle(v) { fstate.theta1 = v; if (!fstate.single) { fstate.single = true; document.getElementById('viewModeInput').checked = true; } render(); }
function update_indexRatio(v) { fstate.ratio = v; render(); }
function toggle_viewMode(on) { fstate.single = on; render(); }
function toggle_showCriticalRef(on) { fstate.showCrit = on; render(); }
function toggle_showReadout(on) { fstate.readout = on; render(); }
function showKeyInsight() {
  showPopup('Key insight', 'Total internal reflection is not a new effect but the point where refraction runs out of room: once θ₂ would have to exceed 90°, Snell\'s law has no solution and all the light must reflect — and that threshold is fixed entirely by sin θ_c = n₂/n₁.');
}

/* ---------- demo steps ---------- */
var STEPS = [
  { t: 'The figure as printed', n: 'Three panels of one boundary between a dense medium n₁ below and a lighter medium n₂ above: in (a) the ray refracts out, in (b) it grazes the surface at θ₂ = 90°, in (c) it is entirely reflected back.', s: { v: false, r: 0.67, c: true, o: false } },
  { t: 'Ordinary refraction (a)', n: 'Switch to the live single panel at a modest angle: the ray splits, part reflecting at θ₁ and part refracting into n₂, bent away from the normal so θ₂ > θ₁.', s: { v: true, a: 25, r: 0.67, c: true, o: true } },
